// Written by scripts/vocabulary.ts: do not edit.

/** Where the vocabulary was copied from: tss.ttl of the specification, at one commit. */
export const TSS_VOCABULARY_SOURCE = "https://raw.githubusercontent.com/KNowledgeOnWebScale/rdf-tss/a1195c90787b342f5a779ee2b7d87120c7735958/tss.ttl";

/**
 * The TSS vocabulary (tss.ttl) of the specification, as Turtle. Among its terms are the
 * alignment of the points with SOSA, QUDT and SAREF: `tss:Point` is a `sosa:Observation`
 * and a `saref:Measurement`, `tss:time` and `tss:value` are subproperties of their
 * properties, and property chains over `tss:field` carry what a value field observes.
 */
export const TSS_VOCABULARY = "@prefix tss:     <https://w3id.org/tss#> .\n@prefix owl:     <http://www.w3.org/2002/07/owl#> .\n@prefix rdf:     <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .\n@prefix rdfs:    <http://www.w3.org/2000/01/rdf-schema#> .\n@prefix xsd:     <http://www.w3.org/2001/XMLSchema#> .\n@prefix dcterms: <http://purl.org/dc/terms/> .\n@prefix vann:    <http://purl.org/vocab/vann/> .\n@prefix skos:    <http://www.w3.org/2004/02/skos/core#> .\n@prefix dcat:    <http://www.w3.org/ns/dcat#> .\n@prefix prov:    <http://www.w3.org/ns/prov#> .\n@prefix csvw:    <http://www.w3.org/ns/csvw#> .\n@prefix sosa:    <http://www.w3.org/ns/sosa/> .\n@prefix qudt:    <http://qudt.org/schema/qudt/> .\n@prefix saref:   <https://saref.etsi.org/core/> .\n@prefix prof:    <http://www.w3.org/ns/dx/prof/> .\n\n# The terms of the RDF Time Series Sources vocabulary (tss:): the source and its five classes,\n# its fields, the summaries of their values, the points of an embedded source, and the values\n# they take.\n#\n# \"A time of the source\" below is an xsd:dateTime literal with a timezone (Z or an offset such\n# as +02:00), which is not left out; xsd:dateTimeStamp is allowed too. These are:\n#   on the source:   tss:from, tss:until, tss:timeBase\n#   on a summary:     tss:firstTime, tss:lastTime, tss:generatedAtTime\n#   in a row:         the value of the source's tss:timeField, stated on every point with tss:time\n\n<https://w3id.org/tss#> a owl:Ontology ;\n    dcterms:title \"RDF Time Series Sources\"@en ;\n    dcterms:description \"Vocabulary for describing time series sources in RDF: a source, its fields and how to read their values, the summaries of those values, and the points of a source whose readings are embedded in its metadata.\"@en ;\n    dcterms:modified \"2026-11-20\"^^xsd:date ;\n    rdfs:comment \"This ontology lists the terms of the RDF Time Series Sources specification. The specification is normative: it states the cardinalities, the datatypes of the values and the other rules that this ontology does not express. Terms of other vocabularies are aligned with rdfs:subClassOf and rdfs:subPropertyOf where that holds without side effects, and with skos:closeMatch where the domain or range of the other term would not fit.\"@en ;\n    rdfs:seeAlso <https://knowledgeonwebscale.github.io/rdf-tss/> ;\n    dcterms:contributor <https://pietercolpaert.be/#me>, <https://www.linkedin.com/in/shehabeldeen-abdelfatah-289123365/> ;\n    vann:preferredNamespacePrefix \"tss\" ;\n    vann:preferredNamespaceUri \"https://w3id.org/tss#\" .\n\n\ntss:Source a owl:Class ;\n    rdfs:label \"Source\"@en ;\n    rdfs:comment \"A time series source: the readings of one or more time series in a time window, described by the source's fields. A source is an instance of exactly one of the five subclasses of tss:Source, which says where its readings are and how they are written: in the metadata itself (tss:EmbeddedJSONSource, tss:EmbeddedRDFSource) or in an external data file (tss:ParquetSource, tss:CSVSource, tss:ArrowSource). A metadata document describes one or more sources, all embedded or all with an external data file, and each is read on its own.\"@en ;\n    rdfs:subClassOf dcat:Dataset ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:EmbeddedJSONSource a owl:Class ;\n    rdfs:label \"Embedded JSON source\"@en ;\n    rdfs:comment \"A source whose readings are in the metadata itself, as JSON: one rdf:JSON literal, tss:points, holds a JSON array with one object per row, keyed by the tss:columnName of the source's fields.\"@en ;\n    rdfs:subClassOf tss:Source ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:EmbeddedRDFSource a owl:Class ;\n    rdfs:label \"Embedded RDF source\"@en ;\n    rdfs:comment \"A source whose readings are in the metadata itself, as RDF points: each reading is a node (tss:Point) that the source links to with tss:hasPoint, with its value field (tss:field, which may be left out when the source has one value field), its time (tss:time) and its reading (tss:value). The points of one time form a row. The metadata document of a growing source of this class is an RDF Message Log, to which each new row is appended as one message.\"@en ;\n    rdfs:subClassOf tss:Source ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:ParquetSource a owl:Class ;\n    rdfs:label \"Parquet source\"@en ;\n    rdfs:comment \"A source whose readings are the rows of an external Apache Parquet data file (tss:dataFile). A Parquet file cannot be appended to in place: a growing Parquet source is rewritten as a whole, and cannot state tss:rangeRequests true.\"@en ;\n    rdfs:subClassOf tss:Source ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:CSVSource a owl:Class ;\n    rdfs:label \"CSV source\"@en ;\n    rdfs:comment \"A source whose readings are the rows of an external CSV data file (tss:dataFile). tss:delimiter, tss:encoding and tss:header describe how the file is written.\"@en ;\n    rdfs:subClassOf tss:Source ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:ArrowSource a owl:Class ;\n    rdfs:label \"Arrow source\"@en ;\n    rdfs:comment \"A source whose readings are the rows of an external Apache Arrow data file (tss:dataFile), in the Arrow IPC streaming format or in the Arrow IPC file format. A source that states tss:rangeRequests true uses the streaming format, to which record batches are appended in place; a growing source in the file format is rewritten as a whole.\"@en ;\n    rdfs:subClassOf tss:Source ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\n[] a owl:AllDisjointClasses ;\n    owl:members ( tss:EmbeddedJSONSource tss:EmbeddedRDFSource tss:ParquetSource tss:CSVSource tss:ArrowSource ) .\n\ntss:Field a owl:Class ;\n    rdfs:label \"Field\"@en ;\n    rdfs:comment \"A field of a source: one column of its rows, such as the time or one series of values. It says where its values are (tss:columnName, tss:columnIndex), how to read them (tss:datatype). A field is never itself the predicate of its values. Every field is a tss:ValueField or a tss:ContextField.\"@en ;\n    skos:closeMatch csvw:Column ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:ValueField a owl:Class ;\n    rdfs:label \"Value field\"@en ;\n    rdfs:comment \"A field whose values are readings: each of its values, with the time of its row, is a tss:Point, which states the value with tss:value and links to the field with tss:field. What the readings mean is stated on the field (tss:observedProperty, tss:unit, tss:sensor, tss:featureOfInterest).\"@en ;\n    rdfs:subClassOf tss:Field ;\n    owl:disjointWith tss:ContextField ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:ContextField a owl:Class ;\n    rdfs:label \"Context field\"@en ;\n    rdfs:comment \"A field whose values are not readings, but give the context of a row or of the points in it: the time field, the step field, a describing field, or another field such as an identifier. Only the values of the time field (with tss:time) and of describing fields (with their tss:property) are stated on the points. Called tss:MetaField in earlier drafts.\"@en ;\n    rdfs:subClassOf tss:Field ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:Point a owl:Class ;\n    rdfs:label \"Point\"@en ;\n    rdfs:comment \"One reading: the value of one value field in one row of a source, with the time of that row. A point states its value field (tss:field), its time (tss:time), its reading (tss:value), and the values of the describing fields that describe its value field, each with the tss:property of that describing field. A point of a source with exactly one value field may leave out tss:field; an expanded point always states it. A point is a blank node, or an IRI given in the RDF points or made with tss:aboutUrl. Aligned with sosa:Observation and saref:Measurement.\"@en ;\n    rdfs:subClassOf sosa:Observation, saref:Measurement ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:Summary a owl:Class ;\n    rdfs:label \"Summary\"@en ;\n    rdfs:comment \"Statistics of the values of one field in the time window of its source, calculated from the readings. A summary has no window of its own. Every attribute of a summary is optional.\"@en ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:MissingValuePolicy a owl:Class ;\n    rdfs:label \"Missing value policy\"@en ;\n    rdfs:comment \"How a summary treats empty values, such as tss:ExcludeEmptyValues.\"@en ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:ValueEncoding a owl:Class ;\n    rdfs:label \"Value encoding\"@en ;\n    rdfs:comment \"How the values of a field are stated when they are not the readings themselves, such as tss:DeltaFromBaseline.\"@en ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\n\n#################################################################\n#    Individuals\n#################################################################\n\ntss:ExcludeEmptyValues a tss:MissingValuePolicy ;\n    rdfs:label \"Exclude empty values\"@en ;\n    rdfs:comment \"Empty values are not values: nulls, absent values and empty strings (\\\"\\\") are left out of tss:count and of every statistic, and tss:missing counts them. A string of only whitespace is a value. An empty string and no value are the same thing, so the empty string cannot be the value of a field.\"@en ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:DeltaFromBaseline a tss:ValueEncoding ;\n    rdfs:label \"Delta from baseline\"@en ;\n    rdfs:comment \"Each value of the field in the source's data file is the difference from the field's tss:baseline: the reading is tss:baseline + the stated value, summed exactly on the decimal values of the two literals and then read as the field's tss:datatype. The field's tss:minimum, tss:maximum and tss:summary describe the readings, not the differences.\"@en ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\n\n#################################################################\n#    Properties of a source\n#################################################################\n\ntss:from a owl:DatatypeProperty, owl:FunctionalProperty ;\n    rdfs:label \"from\"@en ;\n    rdfs:comment \"The start of the source's time window, included: the window its readings cover. A summary has no window of its own: it covers the source's window. A time of the source.\"@en ;\n    rdfs:domain tss:Source ;\n    rdfs:range xsd:dateTime ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:until a owl:DatatypeProperty, owl:FunctionalProperty ;\n    rdfs:label \"until\"@en ;\n    rdfs:comment \"The end of the source's time window, not included; it comes after tss:from. A time of the source.\"@en ;\n    rdfs:domain tss:Source ;\n    rdfs:range xsd:dateTime ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:immutable a owl:DatatypeProperty, owl:FunctionalProperty ;\n    rdfs:label \"immutable\"@en ;\n    rdfs:comment \"true when the source is final: no reading is added, changed or removed, and its description does not change any more. false, or not stated, when the source is growing: it is append-only, so readings may be added, but none is changed or removed, and its description does not change. A source that states true never becomes growing again. Named after ldes:immutable.\"@en ;\n    rdfs:domain tss:Source ;\n    rdfs:range xsd:boolean ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:rangeRequests a owl:DatatypeProperty, owl:FunctionalProperty ;\n    rdfs:label \"range requests\"@en ;\n    rdfs:comment \"true when the publisher promises that, while the source grows, the bytes that hold its rows only grow: every representation of its RDF Message Log (tss:EmbeddedRDFSource) or data file (tss:CSVSource, or tss:ArrowSource in the IPC streaming format), without content coding, is a byte prefix of every later one, and the resource is not compressed as a whole. A consumer then follows the source with HTTP Range requests for the new bytes only. false, or not stated: the publisher may write the document or data file anew on every change, and a consumer reads it again as a whole.\"@en ;\n    rdfs:domain tss:Source ;\n    rdfs:range xsd:boolean ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:producedBy a owl:ObjectProperty, owl:FunctionalProperty ;\n    rdfs:label \"produced by\"@en ;\n    rdfs:comment \"The system that produced the readings of the source.\"@en ;\n    rdfs:domain tss:Source ;\n    rdfs:subPropertyOf prov:wasAttributedTo ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:sourceDescription a owl:ObjectProperty, owl:FunctionalProperty ;\n    rdfs:label \"source description\"@en ;\n    rdfs:comment \"A node that describes the source with any RDF vocabulary and properties.\"@en ;\n    rdfs:domain tss:Source ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:hasField a owl:ObjectProperty ;\n    rdfs:label \"has field\"@en ;\n    rdfs:comment \"A field of the source. Every field is a field of exactly one source.\"@en ;\n    rdfs:domain tss:Source ;\n    rdfs:range tss:Field ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:timeField a owl:ObjectProperty, owl:FunctionalProperty ;\n    rdfs:label \"time field\"@en ;\n    rdfs:comment \"The field of the source that holds the time of each reading. Its values are times of the source, so its tss:datatype is xsd:dateTime (or xsd:dateTimeStamp), and every time has a timezone. In a source with a time grid the data file has no column for it: a row's time is computed from its step, given by tss:stepField or by the row's position in the data file.\"@en ;\n    rdfs:domain tss:Source ;\n    rdfs:range tss:Field ;\n    rdfs:subPropertyOf tss:hasField ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:key a owl:ObjectProperty, owl:FunctionalProperty ;\n    rdfs:label \"key\"@en ;\n    rdfs:comment \"The field of the source whose values identify a reading: always its tss:timeField. A source states at most one tss:key, and it is the time field; a source without tss:key has its time field as key too. No two readings have the same time; two times that are the same moment are the same time.\"@en ;\n    rdfs:domain tss:Source ;\n    rdfs:range tss:Field ;\n    rdfs:subPropertyOf tss:hasField ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\n\n#################################################################\n#    Properties of an embedded source\n#################################################################\n\ntss:hasPoint a owl:ObjectProperty ;\n    rdfs:label \"has point\"@en ;\n    rdfs:comment \"A point of the source: one reading. A tss:EmbeddedRDFSource states its points with tss:hasPoint; the expansion of a source of any class does too. Every point is a point of exactly one source, and every object of tss:hasPoint is a point.\"@en ;\n    rdfs:domain tss:Source ;\n    rdfs:range tss:Point ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:points a owl:DatatypeProperty, owl:FunctionalProperty ;\n    rdfs:label \"points\"@en ;\n    rdfs:comment \"The readings of a tss:EmbeddedJSONSource: one rdf:JSON literal whose value is a JSON array with one JSON object per row: one time, and the values of the fields at that time. The keys of an object are the tss:columnName of the source's fields, and each value should be a JSON string that holds the lexical form of its field's tss:datatype. A missing key, null and the empty string \\\"\\\" are no value. No key starts with @. The objects are unordered, and \\\"[]\\\" holds no readings.\"@en ;\n    rdfs:domain tss:EmbeddedJSONSource ;\n    rdfs:range rdf:JSON ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\n\n#################################################################\n#    Properties of a source with an external data file\n#################################################################\n\ntss:dataFile a owl:ObjectProperty, owl:FunctionalProperty ;\n    rdfs:label \"data file\"@en ;\n    rdfs:comment \"The external data file that holds the readings of a tss:ParquetSource, tss:CSVSource or tss:ArrowSource; the class of the source says how to read it. A relative IRI is resolved against the metadata document.\"@en ;\n    rdfs:domain tss:Source ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:delimiter a owl:DatatypeProperty, owl:FunctionalProperty ;\n    rdfs:label \"delimiter\"@en ;\n    rdfs:comment \"The one character that separates the columns of the data file of a tss:CSVSource; \\\",\\\" when not stated.\"@en ;\n    rdfs:domain tss:Source ;\n    rdfs:range xsd:string ;\n    skos:closeMatch csvw:delimiter ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:encoding a owl:DatatypeProperty, owl:FunctionalProperty ;\n    rdfs:label \"encoding\"@en ;\n    rdfs:comment \"The character encoding of the data file of a tss:CSVSource; \\\"utf-8\\\" when not stated.\"@en ;\n    rdfs:domain tss:Source ;\n    rdfs:range xsd:string ;\n    skos:closeMatch csvw:encoding ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:header a owl:DatatypeProperty, owl:FunctionalProperty ;\n    rdfs:label \"header\"@en ;\n    rdfs:comment \"true when the first row of the data file of a tss:CSVSource holds the column names; true when not stated.\"@en ;\n    rdfs:domain tss:Source ;\n    rdfs:range xsd:boolean ;\n    skos:closeMatch csvw:header ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\n\n#################################################################\n#    The time grid of a source with an external data file\n#################################################################\n\ntss:timeBase a owl:DatatypeProperty, owl:FunctionalProperty ;\n    rdfs:label \"time base\"@en ;\n    rdfs:comment \"The time of step 0 of the source's time grid: step n is at tss:timeBase + n × tss:timeStep. A time of the source. It anchors the grid and is not a bound of the time window, so it stays the same when tss:from or tss:until change. Only a source with an external data file (a tss:ParquetSource, tss:CSVSource or tss:ArrowSource) has a time grid; it states tss:timeBase and tss:timeStep together, or neither. The points of an embedded source state their own time.\"@en ;\n    rdfs:domain tss:Source ;\n    rdfs:range xsd:dateTime ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:timeStep a owl:DatatypeProperty, owl:FunctionalProperty ;\n    rdfs:label \"time step\"@en ;\n    rdfs:comment \"The time between two steps of the source's time grid: a duration of more than zero, such as PT15M or P1M. Step n is at tss:timeBase + n × tss:timeStep: each part of the step (years, months, days, hours, minutes, seconds) is multiplied by n, and the result is added to tss:timeBase as XML Schema adds a duration to an xsd:dateTime. With years or months the steps are calendar steps, not equal lengths of time: a month has 28 to 31 days, and a day past the end of a month becomes its last day (2021-01-31 + P1M is 2021-02-28). Only a source with an external data file (a tss:ParquetSource, tss:CSVSource or tss:ArrowSource) has a time grid; it states tss:timeBase and tss:timeStep together, or neither.\"@en ;\n    rdfs:domain tss:Source ;\n    rdfs:range xsd:duration ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:stepField a owl:ObjectProperty, owl:FunctionalProperty ;\n    rdfs:label \"step field\"@en ;\n    rdfs:comment \"The field of a source with a time grid whose column holds the step of each row: a whole number, 0 or more, and no two rows at the same step. A row's time is tss:timeBase + its step × tss:timeStep, so the data file has no column for the tss:timeField. The step field is one of the source's fields (tss:hasField), has tss:datatype xsd:integer and is not its tss:timeField. A source with a time grid states at most one tss:stepField; without one, the step of a row is its position in the data file (the first row at step 0), so every step has a row. A source without a time grid states none.\"@en ;\n    rdfs:domain tss:Source ;\n    rdfs:range tss:Field ;\n    rdfs:subPropertyOf tss:hasField ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\n\n#################################################################\n#    Properties of a field\n#################################################################\n\ntss:columnName a owl:DatatypeProperty, owl:FunctionalProperty ;\n    rdfs:label \"column name\"@en ;\n    rdfs:comment \"The name of the field's column in a data file, or its key in the JSON rows of a tss:EmbeddedJSONSource; unique within its source. Required for a field of an external source (except the time field of a source with a time grid) and of a tss:EmbeddedJSONSource; for a field of a tss:EmbeddedRDFSource, required for a describing field that states no tss:property. The default property of a describing field is made from it.\"@en ;\n    rdfs:domain tss:Field ;\n    rdfs:range xsd:string ;\n    skos:closeMatch csvw:name ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:columnIndex a owl:DatatypeProperty, owl:FunctionalProperty ;\n    rdfs:label \"column index\"@en ;\n    rdfs:comment \"The position of the field's column, unique within its source: a whole number, and the first column is 0. Optional when tss:columnName identifies the column.\"@en ;\n    rdfs:domain tss:Field ;\n    rdfs:range xsd:integer ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:datatype a owl:ObjectProperty, owl:FunctionalProperty ;\n    rdfs:label \"datatype\"@en ;\n    rdfs:comment \"The datatype that reads the field's values. In a tss:EmbeddedRDFSource, every value of the field is a literal of this datatype. In the JSON points of a tss:EmbeddedJSONSource and in a data file, it interprets the text of each value; a data file keeps its native types.\"@en ;\n    rdfs:domain tss:Field ;\n    rdfs:range rdfs:Datatype ;\n    skos:closeMatch csvw:datatype ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:language a owl:DatatypeProperty, owl:FunctionalProperty ;\n    rdfs:label \"language\"@en ;\n    rdfs:comment \"The language tag of the values of a field whose tss:datatype is rdf:langString.\"@en ;\n    rdfs:domain tss:Field ;\n    rdfs:range xsd:language ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:minimum a owl:DatatypeProperty, owl:FunctionalProperty ;\n    rdfs:label \"minimum\"@en ;\n    rdfs:comment \"The expected smallest reading of the field: a number. It is informative: a reading below it is still a reading of the field.\"@en ;\n    rdfs:domain tss:Field ;\n    rdfs:range rdfs:Literal ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:maximum a owl:DatatypeProperty, owl:FunctionalProperty ;\n    rdfs:label \"maximum\"@en ;\n    rdfs:comment \"The expected largest reading of the field: a number, not below tss:minimum. It is informative: a reading above it is still a reading of the field.\"@en ;\n    rdfs:domain tss:Field ;\n    rdfs:range rdfs:Literal ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:observedProperty a owl:ObjectProperty, owl:FunctionalProperty ;\n    rdfs:label \"observed property\"@en ;\n    rdfs:comment \"The property that the field's readings are values of.\"@en ;\n    rdfs:domain tss:ValueField ;\n    skos:closeMatch sosa:observedProperty ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:unit a owl:ObjectProperty, owl:FunctionalProperty ;\n    rdfs:label \"unit\"@en ;\n    rdfs:comment \"The unit of the field's readings.\"@en ;\n    rdfs:domain tss:Field ;\n    skos:closeMatch qudt:hasUnit ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:sensor a owl:ObjectProperty, owl:FunctionalProperty ;\n    rdfs:label \"sensor\"@en ;\n    rdfs:comment \"The sensor that made the field's readings.\"@en ;\n    rdfs:domain tss:ValueField ;\n    skos:closeMatch sosa:madeBySensor ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:featureOfInterest a owl:ObjectProperty, owl:FunctionalProperty ;\n    rdfs:label \"feature of interest\"@en ;\n    rdfs:comment \"The thing whose property the field's readings are values of.\"@en ;\n    rdfs:domain tss:ValueField ;\n    skos:closeMatch sosa:hasFeatureOfInterest ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:fieldDescription a owl:ObjectProperty, owl:FunctionalProperty ;\n    rdfs:label \"field description\"@en ;\n    rdfs:comment \"A node that describes the field with any RDF vocabulary and properties.\"@en ;\n    rdfs:domain tss:Field ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:describesField a owl:ObjectProperty ;\n    rdfs:label \"describes field\"@en ;\n    rdfs:comment \"Another field of the same source that this field's values are about: in each reading, this field's value describes that field's value.\"@en ;\n    rdfs:domain tss:ContextField ;\n    rdfs:range tss:ValueField ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:summary a owl:ObjectProperty, owl:FunctionalProperty ;\n    rdfs:label \"summary\"@en ;\n    rdfs:comment \"The summary of the field's values. Only a field of an immutable source has one.\"@en ;\n    rdfs:domain tss:Field ;\n    rdfs:range tss:Summary ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:valueEncoding a owl:ObjectProperty, owl:FunctionalProperty ;\n    rdfs:label \"value encoding\"@en ;\n    rdfs:comment \"How the field's values are stated in the source's data file when they are not the readings themselves. Only a field of a source with an external data file (a tss:ParquetSource, tss:CSVSource or tss:ArrowSource) has one; the points of an embedded source state the readings themselves. A field without a tss:valueEncoding states its readings. The time field has none.\"@en ;\n    rdfs:domain tss:Field ;\n    rdfs:range tss:ValueEncoding ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:baseline a owl:DatatypeProperty, owl:FunctionalProperty ;\n    rdfs:label \"baseline\"@en ;\n    rdfs:comment \"The baseline of a field with tss:valueEncoding tss:DeltaFromBaseline: a number, a literal of the field's tss:datatype. Only such a field has a baseline.\"@en ;\n    rdfs:domain tss:Field ;\n    rdfs:range rdfs:Literal ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\n\n#################################################################\n#    Properties of a summary\n#################################################################\n\ntss:missingValuePolicy a owl:ObjectProperty, owl:FunctionalProperty ;\n    rdfs:label \"missing value policy\"@en ;\n    rdfs:comment \"How the summary treats empty values.\"@en ;\n    rdfs:domain tss:Summary ;\n    rdfs:range tss:MissingValuePolicy ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:count a owl:DatatypeProperty, owl:FunctionalProperty ;\n    rdfs:label \"count\"@en ;\n    rdfs:comment \"How many values the field has in the source's time window: a whole number, 0 or more.\"@en ;\n    rdfs:domain tss:Summary ;\n    rdfs:range xsd:integer ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:missing a owl:DatatypeProperty, owl:FunctionalProperty ;\n    rdfs:label \"missing\"@en ;\n    rdfs:comment \"How many readings in the source's time window have an empty value for the field: a whole number, 0 or more. Readings that do not exist (time gaps) are not counted.\"@en ;\n    rdfs:domain tss:Summary ;\n    rdfs:range xsd:integer ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:firstTime a owl:DatatypeProperty, owl:FunctionalProperty ;\n    rdfs:label \"first time\"@en ;\n    rdfs:comment \"The time of the first reading in the source's time window with a value for the field. A time of the source.\"@en ;\n    rdfs:domain tss:Summary ;\n    rdfs:range xsd:dateTime ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:lastTime a owl:DatatypeProperty, owl:FunctionalProperty ;\n    rdfs:label \"last time\"@en ;\n    rdfs:comment \"The time of the last reading in the source's time window with a value for the field. A time of the source.\"@en ;\n    rdfs:domain tss:Summary ;\n    rdfs:range xsd:dateTime ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:observedMinimum a owl:DatatypeProperty, owl:FunctionalProperty ;\n    rdfs:label \"observed minimum\"@en ;\n    rdfs:comment \"The smallest value of the field in the source's time window: a number. It does not replace the expected tss:minimum.\"@en ;\n    rdfs:domain tss:Summary ;\n    rdfs:range rdfs:Literal ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:observedMaximum a owl:DatatypeProperty, owl:FunctionalProperty ;\n    rdfs:label \"observed maximum\"@en ;\n    rdfs:comment \"The largest value of the field in the source's time window: a number. It does not replace the expected tss:maximum.\"@en ;\n    rdfs:domain tss:Summary ;\n    rdfs:range rdfs:Literal ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:mean a owl:DatatypeProperty, owl:FunctionalProperty ;\n    rdfs:label \"mean\"@en ;\n    rdfs:comment \"The unweighted arithmetic mean of the field's values in the source's time window: a number.\"@en ;\n    rdfs:domain tss:Summary ;\n    rdfs:range rdfs:Literal ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:median a owl:DatatypeProperty, owl:FunctionalProperty ;\n    rdfs:label \"median\"@en ;\n    rdfs:comment \"The median of the field's values in the source's time window: a number. For an even number of values, the mean of the middle two.\"@en ;\n    rdfs:domain tss:Summary ;\n    rdfs:range rdfs:Literal ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:generatedAtTime a owl:DatatypeProperty, owl:FunctionalProperty ;\n    rdfs:label \"generated at time\"@en ;\n    rdfs:comment \"When the summary was calculated. A time of the source. Only an immutable source has summaries: they are computed once, from its final readings.\"@en ;\n    rdfs:domain tss:Summary ;\n    rdfs:range xsd:dateTime ;\n    rdfs:subPropertyOf prov:generatedAtTime ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\n\n#################################################################\n#    Points and the properties of describing fields\n#################################################################\n\ntss:property a owl:ObjectProperty, owl:FunctionalProperty ;\n    rdfs:label \"property\"@en ;\n    rdfs:comment \"The RDF property that states the values of a describing field on the points it describes: in the RDF points of a tss:EmbeddedRDFSource, and in the points that any source is expanded into. Only a describing field states one, and it is unique within its source. When not stated, it is the IRI made of the base IRI (the data file of an external source, the metadata document of an embedded source), '#' and the field's tss:columnName, as CSVW's default propertyUrl {#_name}. It is not rdf:type or a term of this vocabulary. It keeps the meaning of its own vocabulary, and is not aligned with SOSA or SAREF: the value of a describing field says something about a reading, and is not a reading itself.\"@en ;\n    rdfs:domain tss:ContextField ;\n    rdfs:range rdf:Property ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:aboutUrl a owl:DatatypeProperty, owl:FunctionalProperty ;\n    rdfs:label \"about URL\"@en ;\n    rdfs:comment \"A URI template (RFC 6570) that makes the IRI of each point of a value field, as csvw:aboutUrl does for the cells of a column. Its variables are the tss:columnName of the fields of the source, and stand for their values in the row. The result is resolved against the data file of an external source, or the metadata document of an embedded source. Two points of a source never get the same IRI. Not used in a tss:EmbeddedRDFSource, whose points are RDF nodes already. Without it, a point is a blank node.\"@en ;\n    rdfs:domain tss:ValueField ;\n    rdfs:range xsd:string ;\n    skos:closeMatch csvw:aboutUrl ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:field a owl:ObjectProperty, owl:FunctionalProperty ;\n    rdfs:label \"field\"@en ;\n    rdfs:comment \"The value field of a point: the field whose reading the point is. Every point states it, except that a point of a source with exactly one value field may leave it out; the expansion of a source adds it to every point. Through it, a point gets the observed property, sensor, feature of interest and unit of its field.\"@en ;\n    rdfs:domain tss:Point ;\n    rdfs:range tss:ValueField ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:time a owl:DatatypeProperty, owl:FunctionalProperty ;\n    rdfs:label \"time\"@en ;\n    rdfs:comment \"The time of a point: the time of its row, the value of the source's time field, an xsd:dateTime with a timezone. Every point states it.\"@en ;\n    rdfs:domain tss:Point ;\n    rdfs:range xsd:dateTime ;\n    rdfs:subPropertyOf sosa:resultTime, saref:hasTimestamp ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\ntss:value a owl:DatatypeProperty, owl:FunctionalProperty ;\n    rdfs:label \"value\"@en ;\n    rdfs:comment \"The reading of a point: the value of its value field, as a literal of the field's tss:datatype (the decoded value, for a field with a tss:valueEncoding). Every point states it. A property of a domain vocabulary, such as ex:temperature, is derived from tss:field and tss:value with a rule, not with OWL: the values of tss:value are literals, and OWL 2 property chains only follow object properties.\"@en ;\n    rdfs:domain tss:Point ;\n    rdfs:subPropertyOf sosa:hasSimpleResult, saref:hasValue ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n\n\n#################################################################\n#    Alignment of the points with SOSA, QUDT and SAREF\n#################################################################\n\n# The meaning of a value field reaches each of its points through tss:field.\n# Property chains are in OWL 2 RL, so a rule reasoner can derive these.\n\nsosa:observedProperty owl:propertyChainAxiom ( tss:field tss:observedProperty ) .\nsosa:madeBySensor owl:propertyChainAxiom ( tss:field tss:sensor ) .\nsosa:hasFeatureOfInterest owl:propertyChainAxiom ( tss:field tss:featureOfInterest ) .\nqudt:hasUnit owl:propertyChainAxiom ( tss:field tss:unit ) .\n\nsaref:relatesToProperty owl:propertyChainAxiom ( tss:field tss:observedProperty ) .\nsaref:measurementMadeBy owl:propertyChainAxiom ( tss:field tss:sensor ) .\nsaref:isMeasurementOf owl:propertyChainAxiom ( tss:field tss:featureOfInterest ) .\nsaref:isMeasuredIn owl:propertyChainAxiom ( tss:field tss:unit ) .\n\n\n#################################################################\n#    RDF Message Stream Profile\n#################################################################\n\ntss:MessageStreamProfile a prof:Profile ;\n    rdfs:label \"RDF Time Series Sources message stream profile\"@en ;\n    rdfs:comment \"The RDF Message Stream Profile of RDF Time Series Sources. A stream that follows it holds description messages (the description of sources and their fields), row messages (one row of one source: the source tss:hasPoint one point per value field with a value, all with the time of the row) and ending messages (tss:immutable true and optionally the stored summaries). Row messages are read with the description message of their source, which comes before them. The focus nodes of a row message are its points; its timestamp is the time of its row, stated with tss:time. A stream announces it with dcterms:conformsTo or an HTTP Link with rel=profile.\"@en ;\n    prof:isProfileOf <https://w3c-cg.github.io/rsp/spec/messages> ;\n    rdfs:seeAlso <https://knowledgeonwebscale.github.io/rdf-tss/#message-profile> ;\n    rdfs:isDefinedBy <https://w3id.org/tss#> .\n";
